<script setup>
import { reactive, watch } from 'vue'
const props=defineProps({open:Boolean,specs:Object});const emit=defineEmits(['close','save']);const form=reactive({})
watch(()=>props.open,(open)=>{if(open)Object.assign(form,JSON.parse(JSON.stringify(props.specs)))},{immediate:true})
const labels={avg:'AVG',range:'RANGE',point:'POINT',stress:'STRESS'}
</script>
<template><div v-if="open" class="backdrop" @click.self="emit('close')"><section class="dialog" role="dialog"><header><div><span>SPECIFICATION</span><h2>Spec 기준 설정</h2><p>지표별 관리 하한과 상한을 설정합니다.</p></div><button @click="emit('close')">×</button></header><div class="spec-list"><article v-for="(value,key) in form" :key="key"><b>{{ labels[key] }}</b><label>하한 (LSL)<input v-model.number="value.min" type="number" step="0.1"></label><label>상한 (USL)<input v-model.number="value.max" type="number" step="0.1"></label></article></div><footer><button class="cancel" @click="emit('close')">취소</button><button class="save" @click="emit('save',form)">적용</button></footer></section></div></template>
<style scoped>.backdrop{position:fixed;z-index:100;inset:0;display:grid;place-items:center;padding:20px;background:rgba(2,7,13,.72);backdrop-filter:blur(4px)}.dialog{width:min(620px,100%);padding:22px;background:#142132;border:1px solid #38506a;border-radius:14px;box-shadow:0 25px 70px #02060c}.dialog header{display:flex;justify-content:space-between}.dialog header span{color:var(--blue);font-size:8px;font-weight:800;letter-spacing:.14em}.dialog h2{margin-top:4px;font-size:18px}.dialog p{margin-top:4px;color:var(--muted);font-size:10px}.dialog header button{width:30px;height:30px;color:#8296aa;background:#101b29;border:1px solid var(--border);border-radius:7px;font-size:18px}.spec-list{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:20px}.spec-list article{display:grid;grid-template-columns:1fr 1fr;gap:9px;padding:14px;background:#101b29;border:1px solid var(--border);border-radius:9px}.spec-list b{grid-column:1/-1;color:#b7c6d5;font-size:10px}.spec-list label{display:grid;gap:5px;color:#657a90;font-size:8px}.spec-list input{width:100%;height:34px;padding:0 8px;color:#dce7f1;background:#0d1723;border:1px solid #2c4056;border-radius:6px}.dialog footer{display:flex;justify-content:flex-end;gap:8px;margin-top:20px}.dialog footer button{padding:9px 16px;border-radius:7px;font-size:10px;font-weight:700}.cancel{color:#8498ab;background:transparent;border:1px solid var(--border)}.save{color:#07121d;background:var(--blue);border:0}@media(max-width:560px){.spec-list{grid-template-columns:1fr}}</style>
